{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Verapamil, a dimethoxyphenyl tertiary amine with extensive first-pass metabolism, has an absolute oral bioavailability of 34% in humans, supporting F ≥20% for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Noscapine, a dimethoxy-substituted isoquinoline alkaloid, has an absolute oral bioavailability of 30% in healthy volunteers, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Sulpiride, a basic benzamide with a sulfonamide, has an oral bioavailability of 27% in humans, supporting F ≥20% despite incomplete absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Encainide, a basic dimethoxyphenyl amide, has an absolute oral bioavailability of 32±7% in normal subjects, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C61"],
      "claim": "Alfentanil, a basic N-aryl amide, has an absolute oral bioavailability of 42±15% in volunteers, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Levosulpiride, the enantiomer of sulpiride, has an absolute oral bioavailability of 23.4% in Chinese volunteers, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Valbenazine, a dimethoxy-substituted tetrahydroisoquinoline prodrug, has an absolute oral bioavailability of ~49% in humans, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Colchicine, a trimethoxy-substituted alkaloid, has a mean absolute oral bioavailability of 55% in elderly subjects, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Codeine, a basic morphinan, has an oral bioavailability of 42-71% in healthy volunteers, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C71"],
      "claim": "In 20 normal young men, verapamil bioavailability averaged 19.4% after single oral doses, slightly below the 20% threshold, indicating that some close analogs can fall below threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query molecule is a basic, lipophilic dimethoxyphenyl-containing tertiary amine with lactam and tetrahydroisoquinoline-like motifs. Multiple close structural analogs (verapamil, noscapine, sulpiride, encainide, alfentanil, levosulpiride, valbenazine, colchicine, codeine) have measured oral bioavailability values mostly between 23% and 55%, all above the 20% threshold. Although one verapamil study reported 19.4% and the physicochemical prior is mixed, the preponderance of transferable experimental evidence supports F ≥20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the exact query molecule.",
    "The query's low neutral fraction (0.02) due to basic pKa 9.05 may reduce passive absorption, but similar basic drugs still achieve F ≥20%.",
    "First-pass metabolism and transporter effects for the query are unknown.",
    "Formulation and dose effects were not assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

